import sys
from itertools import accumulate
from math import sqrt

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def max_primes(tiles):
    return sum(is_prime(s) for s in accumulate(tiles))

n = int(sys.stdin.readline())
tiles = list(map(int, sys.stdin.readline().split()))

ones = tiles.count(1)
twos = n - ones

result = [1] * ones + [2] * twos
current_max_primes = max_primes(result)

for i in range(1, n):
    if tiles[i] != result[i]:
        result[i], result[i - 1] = result[i - 1], result[i]
        new_max_primes = max_primes(result)
        if new_max_primes > current_max_primes:
            current_max_primes = new_max_primes
        else:
            result[i], result[i - 1] = result[i - 1] result[i]

print(' '.join(map(str, result)))
